rawInput.command:
$p='controller/reflex.ts'; $s=Get-Content $p -Raw
$old=@'
    out[0] = base[0] as number;
    out[1] = base[1] as number;
    out[2] = base[2] as number;
'@
$new=@'
    // Step into the push: command a velocity along the pelvis velocity error, in the body yaw frame.
    const q = _s.qpos, w = q[3] as number, x = q[4] as number, y = q[5] as number, z = q[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), s = Math.sin(yaw);
    const wx = _s.qvel[0] as number, wy = _s.qvel[1] as number;
    const bx = c * wx + s * wy, by = -s * wx + c * wy;
    const ex = bx - (base[0] as number), ey = by - (base[1] as number);
    const K = 0.6, DEAD = 0.15; // gain (1), deadband (m/s)
    const gx = Math.abs(ex) > DEAD ? K * ex : 0, gy = Math.abs(ey) > DEAD ? K * ey : 0;
    const cl = (v: number): number => Math.max(-0.8, Math.min(0.8, v));
    out[0] = cl((base[0] as number) + gx);
    out[1] = cl((base[1] as number) + gy);
    out[2] = base[2] as number;
'@
$s=$s.Replace($old.Trim(),$new.Trim()); Set-Content $p $s
npx --no-install golem-spec gate; "exit=$LASTEXITCODE"

